//! Compatibility tests against the fixture generated by the Go implementation.

use std::net::IpAddr;
use std::sync::Arc;

use base64::Engine;
use pm_database::{Databases, MemoryStorage, Options as DbOptions};
use pm_intel::{
    bloom_cache_key, cache_interface, decode_file, list_cache_key, BloomFilterRecord,
    CacheVersionRecord, EntityRecord, FilterLists, ListEntry, Ring, ScopedBloom, CACHE_VERSION_KEY,
    RESET_VERSION,
};
use serde_json::Value;

fn fixture() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../fixtures/m0/intel.json");
    let text = std::fs::read_to_string(path).unwrap();
    serde_json::from_str(&text).unwrap()
}

fn base64(value: &str) -> Vec<u8> {
    base64::engine::general_purpose::STANDARD
        .decode(value)
        .unwrap()
}

fn cache_databases() -> Arc<Databases> {
    let databases = Arc::new(Databases::without_disk());
    databases
        .register_injected("cache", "Cache database")
        .unwrap();
    databases
        .inject("cache", Box::new(MemoryStorage::new()))
        .unwrap();
    databases
}

fn small_filter_lists(databases: &Arc<Databases>) -> FilterLists {
    FilterLists::with_capacity(cache_interface(databases), 100, 10, 5, 20, 20)
}

#[test]
fn rings_match_go() {
    for case in fixture()["rings"].as_array().unwrap() {
        let elements = case["elements"].as_u64().unwrap() as usize;
        let false_positive = case["false_positive"].as_f64().unwrap();

        let mut ring = Ring::init(elements, false_positive).unwrap();
        assert_eq!(ring.size(), case["size"].as_u64().unwrap(), "{elements}");
        assert_eq!(
            ring.hash_rounds(),
            case["hash"].as_u64().unwrap(),
            "{elements}"
        );

        for value in case["values"].as_array().unwrap() {
            ring.add(value.as_str().unwrap().as_bytes());
        }

        let expected_hex = case["marshal_hex"].as_str().unwrap();
        assert_eq!(
            hex::encode(ring.marshal_binary()),
            expected_hex,
            "{elements}"
        );

        let tests = case["tests"].as_array().unwrap();
        let results = case["test_results"].as_array().unwrap();
        for (value, expected) in tests.iter().zip(results) {
            assert_eq!(
                ring.test(value.as_str().unwrap().as_bytes()),
                expected.as_bool().unwrap(),
                "{}: {value}",
                elements
            );
        }

        // A filter loaded from the Go bytes behaves identically.
        let loaded = Ring::unmarshal_binary(&hex::decode(expected_hex).unwrap()).unwrap();
        assert_eq!(loaded.marshal_binary(), ring.marshal_binary());
        for (value, expected) in tests.iter().zip(results) {
            assert_eq!(
                loaded.test(value.as_str().unwrap().as_bytes()),
                expected.as_bool().unwrap(),
                "loaded {}: {value}",
                elements
            );
        }
    }
}

#[test]
fn scoped_filter_sizes_match_go() {
    let bloom = ScopedBloom::new();
    for entry in fixture()["bf_sizes"].as_array().unwrap() {
        let scope = entry["scope"].as_str().unwrap();
        let ring = bloom.ring(scope).expect("filter for scope");
        assert_eq!(ring.size(), entry["size"].as_u64().unwrap(), "{scope}");
        assert_eq!(
            ring.hash_rounds(),
            entry["hash"].as_u64().unwrap(),
            "{scope}"
        );
    }
    assert_eq!(
        bloom.capacity_report(),
        "domain=0/28755176 asn=0/143776 country=0/4314 ipv4=0/2875518 ipv6=0/287552"
    );
}

#[test]
fn decodes_plain_and_gzipped_files() {
    let fixture = fixture();
    let expected: Vec<ListEntry> = serde_json::from_value(fixture["entries"].clone()).unwrap();

    let plain = base64(fixture["file_plain"].as_str().unwrap());
    let decoded = decode_file(plain.as_slice()).unwrap();
    assert_eq!(decoded, expected);

    let gzipped = base64(fixture["file_gzipped"].as_str().unwrap());
    let decoded = decode_file(gzipped.as_slice()).unwrap();
    assert_eq!(decoded, expected);

    // The decoder rejects unknown contents.
    assert!(decode_file(&b""[..]).is_err());
    assert!(decode_file(&b"XX"[..]).is_err());
    assert!(decode_file(&[pm_dsd::format::LIST, pm_dsd::format::CBOR][..]).is_err());
}

#[test]
fn records_and_lookups_match_go() {
    let fixture = fixture();
    let entries: Vec<ListEntry> = serde_json::from_value(fixture["entries"].clone()).unwrap();
    let records = fixture["records"].as_array().unwrap();
    assert_eq!(entries.len(), records.len());

    let databases = cache_databases();
    let filter_lists = small_filter_lists(&databases);

    // Before loading, nothing is found.
    assert!(filter_lists
        .lookup_domain("example.com.")
        .unwrap()
        .is_empty());

    for (entry, expected) in entries.iter().zip(records) {
        let record = filter_lists.store_entry(entry, 1_700_000_000).unwrap();
        assert_eq!(record.key.to_string(), expected["key"].as_str().unwrap());
        assert_eq!(
            record.meta.is_deleted(),
            expected["deleted"].as_bool().unwrap()
        );

        let entity: EntityRecord = serde_json::from_slice(&record.data).unwrap();
        let sources: Vec<String> = expected["sources"]
            .as_array()
            .unwrap()
            .iter()
            .map(|source| source.as_str().unwrap().to_string())
            .collect();
        assert_eq!(entity.sources, sources);
    }

    filter_lists.set_loaded(true);

    // Listed entities return their sources.
    assert_eq!(
        filter_lists.lookup_domain("example.com.").unwrap(),
        vec!["list-a", "list-b"]
    );
    assert_eq!(
        filter_lists
            .lookup_ip("192.0.2.10".parse::<IpAddr>().unwrap())
            .unwrap(),
        vec!["list-b"]
    );
    // The country record has no sources.
    assert!(filter_lists.lookup_country("XX").unwrap().is_empty());

    // Whitelisted (deleted) records and unlisted entities are not found.
    assert!(filter_lists
        .lookup_domain("removed.example.")
        .unwrap()
        .is_empty());
    assert!(filter_lists
        .lookup_domain("not-listed.example.")
        .unwrap()
        .is_empty());
    assert!(filter_lists.lookup_domain("").unwrap().is_empty());
    assert!(filter_lists.lookup_domain(".").unwrap().is_empty());
    // Unknown scopes never match.
    assert!(filter_lists.lookup_asn("65000").unwrap().is_empty());

    // The entity record of the fixture matches the Go JSON.
    let record = filter_lists
        .cache()
        .get(&list_cache_key("domain", "example.com."))
        .unwrap();
    let entity: EntityRecord = serde_json::from_slice(&record.data).unwrap();
    assert_eq!(entity.value, "example.com.");
}

#[test]
fn record_json_matches_go() {
    let fixture = fixture();

    let entity = EntityRecord {
        value: "example.com.".to_string(),
        sources: vec!["list-a".to_string(), "list-b".to_string()],
        type_: "domain".to_string(),
        updated_at: 1_700_000_000,
    };
    let serialized = String::from_utf8(pm_dsd::gojson::to_vec(&entity).unwrap()).unwrap();
    assert_eq!(serialized, fixture["entity_record"].as_str().unwrap());

    let version = CacheVersionRecord {
        version: "v0.6.4".to_string(),
        reset: "v0.6.0".to_string(),
    };
    let serialized = String::from_utf8(pm_dsd::gojson::to_vec(&version).unwrap()).unwrap();
    assert_eq!(serialized, fixture["version_record"].as_str().unwrap());

    // Go writes `null` for empty slices; it decodes to an empty vector.
    let decoded: EntityRecord =
        serde_json::from_str(r#"{"Value":"x","Sources":null,"Type":"domain","UpdatedAt":0}"#)
            .unwrap();
    assert!(decoded.sources.is_empty());
}

#[test]
fn bloom_cache_round_trip() {
    let databases = cache_databases();

    let filter_lists = small_filter_lists(&databases);
    filter_lists.set_loaded(true);
    let values = ["example.com.", "192.0.2.10", "2001:db8::1", "65000", "XX"];
    for value in values {
        filter_lists
            .store_entry(
                &ListEntry {
                    type_: "domain".to_string(),
                    entity: value.to_string(),
                    resources: vec![pm_intel::EntryResource {
                        source_id: "list-a".to_string(),
                        resource_id: "r1".to_string(),
                    }],
                    ..ListEntry::default()
                },
                1_700_000_000,
            )
            .unwrap();
    }
    filter_lists.save_bloom_cache().unwrap();

    // The records are stored under the Go keys.
    let internal = databases.interface(DbOptions {
        local: true,
        internal: true,
        ..DbOptions::default()
    });
    for scope in ["domain", "asn", "country", "ipv4", "ipv6"] {
        let record = internal.get(&bloom_cache_key(scope)).unwrap();
        let filter: BloomFilterRecord = serde_json::from_slice(&record.data).unwrap();
        assert!(!filter.filter.is_empty());
    }

    // A fresh filter list set loads the filters back.
    let restored = small_filter_lists(&databases);
    restored.load_bloom_cache().unwrap();
    for scope in ["domain", "asn", "country", "ipv4", "ipv6"] {
        assert_eq!(
            filter_lists.bloom_test(scope, "example.com."),
            restored.bloom_test(scope, "example.com."),
            "{scope}"
        );
    }
    assert!(restored.bloom_test("domain", "example.com."));
    assert!(!restored.bloom_test("domain", "not-added.example."));

    // Loading without cached filters fails like in Go.
    let empty = cache_databases();
    let filter_lists = small_filter_lists(&empty);
    assert!(filter_lists.load_bloom_cache().is_err());
}

#[test]
fn cache_version_is_checked() {
    let databases = cache_databases();
    let filter_lists = small_filter_lists(&databases);

    assert!(filter_lists.cache_version().unwrap().is_none());

    filter_lists.set_cache_version("v0.6.4").unwrap();
    let version = filter_lists.cache_version().unwrap().unwrap();
    assert_eq!(version.version, "v0.6.4");
    assert_eq!(version.reset, RESET_VERSION);

    // A record with a different reset version is ignored.
    let internal = databases.interface(DbOptions {
        local: true,
        internal: true,
        ..DbOptions::default()
    });
    internal
        .put(pm_record::Record {
            key: pm_record::Key::parse(CACHE_VERSION_KEY),
            meta: pm_record::Meta::default(),
            format: pm_dsd::format::JSON,
            data: pm_dsd::gojson::to_vec(&CacheVersionRecord {
                version: "v0.1.0".to_string(),
                reset: "v0.1.0".to_string(),
            })
            .unwrap(),
        })
        .unwrap();
    assert!(filter_lists.cache_version().unwrap().is_none());
}

#[test]
fn block_reasons_match_go() {
    let fixture = fixture();
    let expected_json = fixture["block_reason"]["json"].as_str().unwrap();

    let reason = pm_intel::ListBlockReason::new(vec![
        pm_intel::ListMatch::new(
            "example.com.",
            vec!["list-a".to_string(), "list-b".to_string()],
            vec!["list-c".to_string()],
        ),
        pm_intel::ListMatch::new("192.0.2.10", vec!["list-b".to_string()], Vec::new()),
    ]);

    let json = serde_json::to_string(&reason.to_json()).unwrap();
    assert_eq!(json, expected_json);
    assert_eq!(
        reason.to_string(),
        fixture["block_reason"]["string"].as_str().unwrap()
    );
    assert_eq!(
        reason.0[0].to_string(),
        fixture["block_reason"]["match_string"].as_str().unwrap()
    );

    // Like Go, only the wire form is wrapped: it is unmarshalled from the
    // `filterlists` field explicitly.
    let value: serde_json::Value = serde_json::from_str(expected_json).unwrap();
    let matches: Vec<pm_intel::ListMatch> =
        serde_json::from_value(value["filterlists"].clone()).unwrap();
    assert_eq!(pm_intel::ListBlockReason::new(matches), reason);
    assert!(reason.0[1].inactive_lists.is_empty());
    assert!(pm_intel::ListBlockReason::default().is_empty());
}

#[test]
fn split_domains_match_go() {
    let fixture = fixture();
    let cases = fixture["split_domains"].as_array().unwrap();
    assert_eq!(cases.len(), 21);

    for case in cases {
        let domain = case["domain"].as_str().unwrap();
        let expected: Vec<String> = case["parts"]
            .as_array()
            .unwrap()
            .iter()
            .map(|part| part.as_str().unwrap().to_string())
            .collect();
        assert_eq!(pm_intel::split_domain(domain), expected, "{domain:?}");
    }
}

#[test]
fn list_files_are_loaded_from_disk() {
    let fixture = fixture();
    let databases = cache_databases();
    let filter_lists = small_filter_lists(&databases);

    let mut dir = std::env::temp_dir();
    dir.push(format!("pm-intel-lists-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();

    for (name, key) in [
        ("plain.dsdl", "file_plain"),
        ("gzipped.dsdl", "file_gzipped"),
    ] {
        let path = dir.join(name);
        std::fs::write(&path, base64(fixture[key].as_str().unwrap())).unwrap();

        let loaded = filter_lists.load_list_file(&path, 1_700_000_000).unwrap();
        assert_eq!(loaded, 4, "{name}");
    }
    filter_lists.set_loaded(true);

    // The stored entries are found through the bloom filter and the cache.
    assert_eq!(
        filter_lists.lookup_domain("example.com.").unwrap(),
        vec!["list-a", "list-b"]
    );
    assert_eq!(
        filter_lists
            .lookup_ip("192.0.2.10".parse().unwrap())
            .unwrap(),
        vec!["list-b"]
    );
    assert!(filter_lists.lookup_country("XX").unwrap().is_empty());
    assert!(filter_lists
        .lookup_domain("removed.example.")
        .unwrap()
        .is_empty());
    assert!(filter_lists.bloom_test("domain", "example.com."));
    assert!(!filter_lists.bloom_test("domain", "not-listed.example."));

    // Broken files are reported.
    let broken = dir.join("broken.dsdl");
    std::fs::write(&broken, b"XX").unwrap();
    assert!(filter_lists.load_list_file(&broken, 0).is_err());

    let _ = std::fs::remove_dir_all(&dir);
}
